def solve(n):
    m = 2 * n + 1
    p = []
    p.append(0)
    for k in range(2, 2 * n + 2):
        p.append((p[-1] + k) % m)

    counts = [0] * m
    for pos in p:
        counts[pos] += 1

    heads_down = 0
    for c in counts:
        if c % 2 == 1:
            heads_down += 1
    return heads_down

for n in range(1, 11):
    print(f"n={n}, heads_down={solve(n)}")

